import * as math from "std/math"

function bubbleSort(arr: number[]): number[] {
  let i: number = 0;
  while (i < arr.length()) {
    let j: number = 0;
    while (j < arr.length() - 1) {
      if (arr[j] > arr[j + 1]) {
        let temp: number = arr[j];
        arr[j] = arr[j + 1];
        arr[j + 1] = temp;
      }
      j = j + 1;
    }
    i = i + 1;
  }
  return arr;
}

function insertionSort(arr: number[]): number[] {
  let i: number = 1;
  while (i < arr.length()) {
    let temp: number = arr[i];
    let j: number = i - 1;
    while (j >= 0 && arr[j] > temp) {
      arr[j + 1] = arr[j];
      j = j - 1;
    }
    arr[j + 1] = temp;
    i = i + 1;
  }
  return arr;
}

function selectionSort(items: number[]): number[] {
  let i: number = 0;
  while (i < items.length()) {
    let minimum: number = i;
    let j: number = i + 1;
    while (j < items.length()) {
      if (items[j] < items[minimum]) {
        minimum = j;
      }
      j = j + 1;
    }
    if (i !== minimum) {
      let temp: number = items[i];
      items[i] = items[minimum];
      items[minimum] = temp;
    }
    i = i + 1;
  }
  return items;
}

function shellSort(arr: number[]): number[] {
  let gap: number = math.floor(arr.length() / 2);
  while (gap > 0) {
    let i: number = gap;
    while (i < arr.length()) {
      let temp: number = arr[i];
      let j: number = i;
      while (j >= gap && arr[j - gap] > temp) {
        arr[j] = arr[j - gap];
        j = j - gap;
      }
      arr[j] = temp;
      i = i + 1;
    }
    gap = math.floor(gap / 2);
  }
  return arr;
}

function gnomeSort(arr: number[]): number[] {
  if (arr.length() <= 1) {
    return arr;
  }
  let i: number = 1;
  while (i < arr.length()) {
    if (arr[i - 1] <= arr[i]) {
      i = i + 1;
    } else {
      let temp: number = arr[i];
      arr[i] = arr[i - 1];
      arr[i - 1] = temp;
      i = i - 1;
      if (i < 1) {
        i = 1;
      }
    }
  }
  return arr;
}

import * as math from "std/math"

function jumpSearch(array: number[], target: number): number {
  if (array.length() === 0) {
    return -1;
  }
  let stepSize: number = math.floor(math.sqrt(array.length()));
  let current: number = 0;
  let next: number = stepSize;
  while (array[next - 1] < target) {
    current = next;
    next = next + stepSize;
    if (next > array.length()) {
      next = array.length();
      break;
    }
  }
  let index: number = current;
  while (index < next) {
    if (array[index] === target) {
      return index;
    }
    index = index + 1;
  }
  return -1;
}

function interpolationSearch(array: number[], target: number): number {
  let low: number = 0;
  let high: number = array.length() - 1;
  while (low <= high) {
    let lowValue: number = array[low];
    let highValue: number = array[high];
    if (lowValue === highValue) {
      if (array[low] === target) {
        return low;
      }
      return -1;
    }
    let pos: number = math.round(low + ((target - lowValue) * (high - low)) / (highValue - lowValue));
    if (pos < 0 || pos >= array.length()) {
      return -1;
    }
    let currentValue: number = array[pos];
    if (target === currentValue) {
      return pos;
    }
    if (target > currentValue) {
      low = pos + 1;
    } else {
      high = pos - 1;
    }
  }
  return -1;
}

function binarySearchIterative(array: number[], target: number): number | null {
  if (array.length() === 0) {
    return null;
  }
  let start: number = 0;
  let end: number = array.length() - 1;
  if (target < array[start] || target > array[end]) {
    return null;
  }
  let middle: number = math.floor((start + end) / 2);
  while (array[middle] !== target && start <= end) {
    if (target < array[middle]) {
      end = middle - 1;
    } else {
      start = middle + 1;
    }
    middle = math.floor((start + end) / 2);
  }
  if (array[middle] === target) {
    return middle;
  }
  return null;
}

function binarySearchRecursiveRange(array: number[], target: number, start: number, end: number): number | null {
  if (array.length() === 0) {
    return null;
  }
  if (target < array[start] || target > array[end]) {
    return null;
  }
  let middle: number = math.floor((start + end) / 2);
  if (array[middle] === target) {
    return middle;
  }
  if (start > end) {
    return null;
  }
  if (target < array[middle]) {
    return binarySearchRecursiveRange(array, target, start, middle - 1);
  }
  return binarySearchRecursiveRange(array, target, middle + 1, end);
}

function binarySearchRecursive(array: number[], target: number): number | null {
  return binarySearchRecursiveRange(array, target, 0, array.length() - 1);
}

function isSortedArray(arr: number[]): boolean {
  let i: number = 0;
  while (i < arr.length() - 1) {
    if (arr[i] >= arr[i + 1]) {
      return false;
    }
    i = i + 1;
  }
  return true;
}

function absoluteValue(number: number): number {
  if (number < 0) {
    return -number;
  }
  return number;
}

function nthFibonacci(number: number): number {
  let a: number = 0;
  let b: number = 1;
  let i: number = 0;
  while (i < number) {
    let next: number = a + b;
    a = b;
    b = next;
    i = i + 1;
  }
  return a;
}

function nthFibonacciRecursively(number: number): number {
  if (number === 0) {
    return 0;
  }
  if (number <= 2) {
    return 1;
  }
  return nthFibonacciRecursively(number - 1) + nthFibonacciRecursively(number - 2);
}

